class Solution {
public:
    bool containsNearbyAlmostDuplicate(vector<int>& nums, int indexDiff, int valueDiff) {
        int n = nums.size();
        long long w = (long long)valueDiff + 1;
        unordered_map<long long, long long> buckets;

        for (int i = 0; i < n; i++) {
            long long num = nums[i];
            long long b = (num >= 0) ? (num / w) : ((num + 1) / w - 1);

            if (buckets.count(b)) return true;

            auto it = buckets.find(b - 1);
            if (it != buckets.end()) {
                long long d = num - it->second;
                if (d < 0) d = -d;
                if (d <= valueDiff) return true;
            }

            it = buckets.find(b + 1);
            if (it != buckets.end()) {
                long long d = num - it->second;
                if (d < 0) d = -d;
                if (d <= valueDiff) return true;
            }

            buckets[b] = num;

            if (i >= indexDiff) {
                long long oldNum = nums[i - indexDiff];
                long long oldB = (oldNum >= 0) ? (oldNum / w) : ((oldNum + 1) / w - 1);
                if (buckets.count(oldB) && buckets[oldB] == oldNum) buckets.erase(oldB);
            }
        }
        return false;
    }
};
